//! Parser and renderer for OUTPUT patterns containing `{G:P}` placeholders.

use std::fmt;

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum FormatError {
    EmptyFormatter,
    UnclosedPlaceholder,
    UnopenedPlaceholder,
    InvalidEscapeCharacter(usize, char),
    InvalidPadding(String),
}

impl fmt::Display for FormatError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str("[output-format] ")?;
        match self {
            FormatError::EmptyFormatter => f.write_str("output formatter must be set"),
            FormatError::UnclosedPlaceholder => {
                f.write_str("all opened placeholders must be closed by '}'")
            }
            FormatError::UnopenedPlaceholder => {
                f.write_str("an unopened placeholder could not be closed by '}'")
            }
            FormatError::InvalidEscapeCharacter(pos, ch) => {
                write!(f, "invalid escape character of '{}' at '{}'", ch, pos)
            }
            FormatError::InvalidPadding(p) => write!(f, "unable to parse padding of '{}'", p),
        }
    }
}

#[derive(Debug, Clone)]
enum Group {
    Index(usize),
    Name(String),
}

#[derive(Debug, Clone)]
enum Segment {
    Text(String),
    Placeholder { group: Group, padding: Option<usize> },
}

/// Anything that can provide captured values to a formatter.
pub trait Captures {
    fn by_index(&self, index: usize) -> Option<&str>;
    fn by_name(&self, name: &str) -> Option<&str>;
}

#[derive(Debug, Clone)]
pub struct Formatter {
    segments: Vec<Segment>,
}

impl Formatter {
    pub fn parse(pattern: &str) -> Result<Self, FormatError> {
        let mut segments = Vec::new();
        let mut current = String::new();
        let mut in_placeholder = false;
        let mut escaping = false;
        let mut auto_index = 0usize;

        for (pos, ch) in pattern.chars().enumerate() {
            if escaping {
                escaping = false;
                match ch {
                    '{' | '}' | '\\' => current.push(ch),
                    other => return Err(FormatError::InvalidEscapeCharacter(pos, other)),
                }
                continue;
            }
            match ch {
                '\\' => escaping = true,
                '{' if !in_placeholder => {
                    if !current.is_empty() {
                        segments.push(Segment::Text(std::mem::take(&mut current)));
                    }
                    in_placeholder = true;
                }
                '}' => {
                    if !in_placeholder {
                        return Err(FormatError::UnopenedPlaceholder);
                    }
                    let body = std::mem::take(&mut current);
                    segments.push(Self::parse_placeholder(&body, &mut auto_index)?);
                    in_placeholder = false;
                }
                other => current.push(other),
            }
        }
        if in_placeholder {
            return Err(FormatError::UnclosedPlaceholder);
        }
        if !current.is_empty() {
            segments.push(Segment::Text(current));
        }
        Ok(Formatter { segments })
    }

    fn parse_placeholder(body: &str, auto_index: &mut usize) -> Result<Segment, FormatError> {
        let (group_part, padding_part) = match body.split_once(':') {
            Some((g, p)) => (g, Some(p)),
            None => (body, None),
        };
        let padding = match padding_part {
            None | Some("") => None,
            Some(p) => Some(
                p.parse::<usize>()
                    .map_err(|_| FormatError::InvalidPadding(p.to_string()))?,
            ),
        };
        let group = if group_part.is_empty() {
            *auto_index += 1;
            Group::Index(*auto_index)
        } else if let Ok(index) = group_part.parse::<usize>() {
            Group::Index(index)
        } else {
            Group::Name(group_part.to_string())
        };
        Ok(Segment::Placeholder { group, padding })
    }

    pub fn format<C: Captures + ?Sized>(&self, captures: &C) -> String {
        let mut out = String::new();
        for segment in &self.segments {
            match segment {
                Segment::Text(text) => out.push_str(text),
                Segment::Placeholder { group, padding } => {
                    let value = match group {
                        Group::Index(i) => captures.by_index(*i),
                        Group::Name(n) => captures.by_name(n),
                    }
                    .unwrap_or("");
                    match padding {
                        Some(width) => match value.parse::<u64>() {
                            Ok(number) => out.push_str(&format!("{:0width$}", number, width = *width)),
                            Err(_) => out.push_str(value),
                        },
                        None => out.push_str(value),
                    }
                }
            }
        }
        out
    }
}

impl<'h> Captures for regex::Captures<'h> {
    fn by_index(&self, index: usize) -> Option<&str> {
        self.get(index).map(|m| m.as_str())
    }

    fn by_name(&self, name: &str) -> Option<&str> {
        self.name(name).map(|m| m.as_str())
    }
}

/// Captures used by the sort mode: `{0}` is the file name and `{1}` the index.
pub struct SortCaptures {
    pub name: String,
    pub index: String,
}

impl Captures for SortCaptures {
    fn by_index(&self, index: usize) -> Option<&str> {
        match index {
            0 => Some(&self.name),
            1 => Some(&self.index),
            _ => None,
        }
    }

    fn by_name(&self, _name: &str) -> Option<&str> {
        None
    }
}
EOF"}

