//! Natural ordering of strings: runs of digits are compared by their numeric
//! value and whitespace is ignored.

use std::cmp::Ordering;

fn digit(c: Option<char>) -> Option<u32> {
    c.and_then(|c| c.to_digit(10))
}

pub fn compare(left: &str, right: &str) -> Ordering {
    let mut li = left.chars();
    let mut ri = right.chars();
    let mut l = li.next();
    let mut r = ri.next();

    loop {
        while matches!(l, Some(c) if c.is_whitespace()) {
            l = li.next();
        }
        while matches!(r, Some(c) if c.is_whitespace()) {
            r = ri.next();
        }

        let (lc, rc) = match (l, r) {
            (None, None) => return Ordering::Equal,
            (None, Some(_)) => return Ordering::Less,
            (Some(_), None) => return Ordering::Greater,
            (Some(a), Some(b)) => (a, b),
        };

        match (digit(l), digit(r)) {
            (Some(ld), Some(rd)) => {
                if ld == 0 || rd == 0 {
                    // Fractional style comparison: digits compared left aligned.
                    if ld != rd {
                        return ld.cmp(&rd);
                    }
                    loop {
                        l = li.next();
                        r = ri.next();
                        match (digit(l), digit(r)) {
                            (Some(a), Some(b)) => {
                                if a != b {
                                    return a.cmp(&b);
                                }
                            }
                            (Some(_), None) => return Ordering::Greater,
                            (None, Some(_)) => return Ordering::Less,
                            (None, None) => break,
                        }
                    }
                } else {
                    // Integer style comparison: longer run wins, otherwise the
                    // first differing digit decides.
                    let mut last = ld.cmp(&rd);
                    loop {
                        l = li.next();
                        r = ri.next();
                        match (digit(l), digit(r)) {
                            (Some(a), Some(b)) => {
                                if last == Ordering::Equal {
                                    last = a.cmp(&b);
                                }
                            }
                            (Some(_), None) => return Ordering::Greater,
                            (None, Some(_)) => return Ordering::Less,
                            (None, None) => break,
                        }
                    }
                    if last != Ordering::Equal {
                        return last;
                    }
                }
                // `l` and `r` already hold the characters following the numbers.
                continue;
            }
            _ => {
                let ord = lc.cmp(&rc);
                if ord != Ordering::Equal {
                    return ord;
                }
            }
        }
        l = li.next();
        r = ri.next();
    }
}

#[cfg(test)]
mod tests {
    use super::compare;
    use std::cmp::Ordering::*;

    #[test]
    fn basics() {
        assert_eq!(compare("a1", "a2"), Less);
        assert_eq!(compare("a2", "a10"), Less);
        assert_eq!(compare("a 2", "a2"), Equal);
        assert_eq!(compare("a015", "a12"), Less);
        assert_eq!(compare("a01", "a1"), Less);
        assert_eq!(compare("x1.05", "x1.5"), Less);
        assert_eq!(compare("x1.5", "x1.10"), Less);
        assert_eq!(compare("A3", "B"), Less);
        assert_eq!(compare("B", "_x"), Less);
    }
}
EOF"}

