//! Rendering of the input/output map as an ASCII table.

use std::io::{self, Write};
use unicode_width::{UnicodeWidthChar, UnicodeWidthStr};

/// Width of a text as displayed in a terminal, ignoring ANSI SGR sequences.
fn display_width(text: &str) -> usize {
    #[derive(Clone, Copy, PartialEq, Eq)]
    enum State {
        Normal,
        Escape,
        Sequence,
    }

    let width = UnicodeWidthStr::width(text);
    let mut hidden = 0usize;
    let mut state = State::Normal;
    for c in text.chars() {
        state = match state {
            State::Normal => {
                if c == '\u{1b}' {
                    State::Escape
                } else {
                    State::Normal
                }
            }
            State::Escape => {
                if c == '[' {
                    hidden += c.width().unwrap_or(0);
                    State::Sequence
                } else {
                    State::Normal
                }
            }
            State::Sequence => {
                hidden += c.width().unwrap_or(0);
                if c == 'm' {
                    State::Normal
                } else {
                    State::Sequence
                }
            }
        };
    }
    width.saturating_sub(hidden)
}

struct Cell {
    lines: Vec<String>,
    width: usize,
}

impl Cell {
    fn new(text: &str) -> Self {
        let lines: Vec<String> = text.lines().map(str::to_string).collect();
        let width = lines.iter().map(|l| display_width(l)).max().unwrap_or(0);
        Cell { lines, width }
    }
}

fn separator(widths: &[usize]) -> String {
    let mut s = String::from("+");
    for w in widths {
        for _ in 0..w + 2 {
            s.push('-');
        }
        s.push('+');
    }
    s
}

fn write_row(out: &mut impl Write, cells: &[Cell], widths: &[usize]) -> io::Result<()> {
    let height = cells.iter().map(|c| c.lines.len()).max().unwrap_or(0).max(1);
    for line in 0..height {
        let mut s = String::from("|");
        for (cell, width) in cells.iter().zip(widths) {
            s.push(' ');
            let text = cell.lines.get(line).map(String::as_str).unwrap_or("");
            s.push_str(text);
            for _ in display_width(text)..*width {
                s.push(' ');
            }
            s.push_str(" |");
        }
        s.push('\n');
        out.write_all(s.as_bytes())?;
    }
    Ok(())
}

pub fn print(rows: &[(&str, &str)]) -> io::Result<()> {
    let title = [Cell::new("Input"), Cell::new("Output")];
    let body: Vec<[Cell; 2]> = rows
        .iter()
        .map(|(input, output)| [Cell::new(input), Cell::new(output)])
        .collect();

    let mut widths = [title[0].width, title[1].width];
    for row in &body {
        for (i, cell) in row.iter().enumerate() {
            widths[i] = widths[i].max(cell.width);
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    let sep = separator(&widths);
    writeln!(out, "{}", sep)?;
    write_row(&mut out, &title, &widths)?;
    writeln!(out, "{}", sep)?;
    for row in &body {
        write_row(&mut out, row, &widths)?;
    }
    writeln!(out, "{}", sep)?;
    out.flush()
}
