        paint("error", RED_BOLD),
        input,
        err
    );
}

enum Source {
    Regex { regex: Regex, depth: usize, max_depth: Option<usize> },
    Sort(Order),
    Map(HashMap<String, String>),
}

fn regex_source(pattern: &str, opts: &Options) -> Source {
    let regex = Regex::new(pattern).unwrap_or_else(|e| fail(e));
    let depth = opts
        .depth
        .unwrap_or_else(|| pattern.matches('/').count() + 1);
    Source::Regex { regex, depth, max_depth: opts.max_depth }
}

fn path_string(path: &Path) -> String {
    let relative = path.strip_prefix(".").unwrap_or(path);
    relative.to_string_lossy().into_owned()
}

fn with_extension(output: String, input: &str, no_extension: bool) -> String {
    if no_extension {
        return output;
    }
    match Path::new(input).extension() {
        Some(ext) => format!("{}.{}", output, ext.to_string_lossy()),
        None => output,
    }
}

