    opts: &'a Options,
    map: BTreeMap<String, String>,
    failed: bool,
}

impl<'a> Renamer<'a> {
    fn process(&mut self, input: String, output: String) {
        let mut output = output;
        if self.opts.mkdir {
            if let Some(parent) = Path::new(&output).parent() {
                let _ = fs::create_dir_all(parent);
            }
        }
        if !self.opts.overwrite && input != output {
