import itertools, random, subprocess, sys
def jaro(a, b):
    a = list(a); b = list(b)
    la, lb = len(a), len(b)
    if la == 0 and lb == 0: return 1.0
    if la == 0 or lb == 0: return 0.0
    sr = max(la, lb) // 2
    sr = max(sr - 1, 0)
    af = [False]*la; bf = [False]*lb
    m = 0
    for i, ae in enumerate(a):
        mn = i - sr if i > sr else 0
        mx = min(lb, i + sr + 1)
        for j in range(mx):
            if mn <= j and ae == b[j] and not bf[j]:
                af[i] = True; bf[j] = True; m += 1; break
    t = 0
    if m:
        bi = iter([(bf[j], b[j]) for j in range(lb)])
        for i in range(la):
            if af[i]:
                while True:
                    flag, ch2 = next(bi)
                    if not flag: continue
                    if a[i] != ch2: t += 1
                    break
    t //= 2
    if m == 0: return 0.0
    return ((m / la) + (m / lb) + ((m - t) / m)) / 3.0

