    let longs = ["dir", "depth", "no-extension", "generate", "help", "mkdir", "map", "from-file", "max-depth", "quiet", "regex", "sort", "test", "dry-run", "version", "overwrite"];
    let args: Vec<String> = std::env::args().skip(1).collect();
    let pairs: Vec<(String, String)> = args.chunks(2).map(|c| (c[0].clone(), c[1].clone())).collect();
    let mut seed: u64 = 0x12345678;
    let mut rnd = || { seed ^= seed << 13; seed ^= seed >> 7; seed ^= seed << 17; seed };
    let mut found: HashMap<(String,String), String> = HashMap::new();
    for (c1, c2) in &pairs {
        let mut pool: Vec<char> = c1.chars().chain(c2.chars()).collect();
        pool.extend("abcdefghijklmnopqrstuvwxyz".chars());
        let base: Vec<Vec<char>> = vec![c1.chars().collect(), c2.chars().collect()];
        for _ in 0..3_000_000u32 {
            let mut v: Vec<char> = base[(rnd() % 2) as usize].clone();
            let ops = 1 + rnd() % 6;
            for _ in 0..ops {
                let op = rnd() % 3;
                if op == 0 && v.len() > 1 { let i = (rnd() as usize) % v.len(); v.remove(i); }
                else if op == 1 { let i = (rnd() as usize) % (v.len() + 1); let c = pool[(rnd() as usize) % pool.len()]; v.insert(i, c); }
                else { let i = (rnd() as usize) % v.len(); v[i] = pool[(rnd() as usize) % pool.len()]; }
