            if longs.iter().any(|l| l != c1 && l != c2 && strsim::jaro(&s, l) >= j1) { continue; }
            let key = (c1.clone(), c2.clone());
            let better = match found.get(&key) { Some(o) => s.len() < o.len(), None => true };
            if better { found.insert(key, s); }
        }
        if let Some(v) = found.get(&(c1.clone(), c2.clone())) { println!("{} {} {}", c1, c2, v); } else { println!("{} {} NONE", c1, c2); }
    }
}
